(()=>{const out=[];for(const [name,formats]of [['WEBGL_compressed_texture_s3tc',[33776,33777,33778,33779]],['WEBGL_compressed_texture_s3tc_srgb',[35916,35917,35918,35919]],['EXT_texture_compression_rgtc',[36283,36284,36285,36286]],['EXT_texture_compression_bptc',[36492,36493,36494,36495]]])for(const format of formats){const g=new OffscreenCanvas(2,2).getContext('webgl2',{antialias:false}),e=g.getExtension(name),p=g.createProgram();for(const [t,src]of [[g.VERTEX_SHADER,'#version 300 es\nvoid main(){gl_Position=vec4(float(gl_VertexID==1)*2.-1.,float(gl_VertexID==2)*2.-1.,0.,1.);}'],[g.FRAGMENT_SHADER,'#version 300 es\nprecision highp float;uniform sampler2D image;out vec4 color;void main(){color=texture(image,gl_FragCoord.xy/vec2(2.));}']]){const s=g.createShader(t);g.shaderSource(s,src);g.compileShader(s);g.attachShader(p,s)}g.linkProgram(p);g.useProgram(p);const tex=g.createTexture();g.bindTexture(g.TEXTURE_2D,tex);for(const v of [g.TEXTURE_MIN_FILTER,g.TEXTURE_MAG_FILTER])g.texParameteri(g.TEXTURE_2D,v,g.NEAREST);const size=[33776,33777,35916,35917,36283,36284].includes(format)?8:16,blocks=new Uint8Array(size);if(format<36492){blocks[0]=127;blocks[1]=127;}g.compressedTexImage2D(g.TEXTURE_2D,0,format,4,4,0,blocks);const upload=g.getError();g.drawArrays(g.TRIANGLES,0,3);const b=new Uint8Array(16);g.readPixels(0,0,2,2,g.RGBA,g.UNSIGNED_BYTE,b);out.push({name,format,upload,pixels:Array.from(b),error:g.getError()})}return out})()
